INSERT INTO public.movies (movie_id, title, release_date, description, poster_url, duration_minutes, country, original_language, trailer_url) VALUES (1346, 'Straszny Film 3', '2003-10-24', 'Ambitna dziennikarka Cindy Campbell zajmuje się tropieniem zjawisk paranormalnych. Tym razem jej zainteresowanie budzą tajemnicze kręgi, które pojawiły się na polu byłego pastora Toma Logana. Wkrótce najlepsza przyjaciółka Cindy, Brenda, ginie po obejrzeniu pewnej kasety video. Reporterka stara dowieść, czy śmiercionośne nagranie ma jakikolwiek związek ze znakami na polu. Odkrywa, że świat jest zagrożony inwazją kosmitów. Kolejna część parodii horrorów, gdzie tym razem reżyserkę objął po braciach Wayans David Zucker, a w filmie możemy zobaczyć parodię takich filmów jak: "Ring", "Znaki", "8 Mila", "Inni" czy "Matrix".', 'https://image.tmdb.org/t/p/w500/1fmjcoeduyph1iugUpbJeUBwiZE.jpg', 84, 'United States of America', 'en', 'https://www.youtube.com/watch?v=O21wD8Tzr2k');
INSERT INTO public.movies (movie_id, title, release_date, description, poster_url, duration_minutes, country, original_language, trailer_url) VALUES (1345, 'Marzyciele', '2003-10-10', 'Paryż, wiosna 1968. Burzliwe wydarzenia polityczne i społeczne, rewolucyjne zmiany w obyczajowości. Na tym tle rozgrywa się historia trójki młodych ludzi. Francuskie rodzeństwo, Isabelle i Theo, poznaje amerykańskiego studenta Matthew, który przyjechał do Paryża, aby poznać wielką europejską kulturę i historię. Bardzo dobrze czują się w swoim towarzystwie i wkrótce postanawiają zamieszkać razem. Od tej chwili rozpoczyna się wyrafinowana gra emocjonalna i seksualna oparta na kontrowersyjnych zasadach. Wyzwoleni młodzi ludzie prowadzą coraz bardziej niebezpieczne eksperymenty, badając granice, do których mogą się posunąć.', 'https://image.tmdb.org/t/p/w500/ej026VbpAuInE8dFQnvL5Q7axgY.jpg', 106, 'France', 'en', 'https://www.youtube.com/watch?v=9DsxpEA9EUc');
