INSERT INTO public.movies (movie_id, title, release_date, description, poster_url, duration_minutes, country, original_language, trailer_url) VALUES (1154, 'Dziki robot', '2024-09-12', 'ROZZUM jest robotem, jednostką 7134. Rozbija się na niezamieszkanej wyspie i musi nauczyć dostosowywać do surowego otoczenia. Stopniowo zaczyna budować relacje z tamtejszymi zwierzętami i staje się również przybranym rodzicem osieroconej gęsi. Animacja oparta jest na bestsellerowej książce dla dzieci o tym samym tytule i opowiada o odkrywaniu siebie oraz bada, co to znaczy być żywym i połączonym ze wszystkimi istotami.', 'https://image.tmdb.org/t/p/w500/FTd11HGc8FfkBChRCrFAxtjJJm.jpg', 101, 'US', 'en', 'https://www.youtube.com/watch?v=SPMChTR4Pj4');
