INSERT INTO public.movies (movie_id, title, release_date, description, poster_url, duration_minutes, country, original_language, trailer_url) VALUES (1203, 'Co Kryje Prawda', '2000-07-21', 'Szczęśliwe małżeństwo, Claire (Michelle Pfeiffer) i Norman (Harrison Ford) Spencerowie, zamieszkuje w nowym domu nad jeziorem. Wyjazd na studia ich córki Caitlin (Katharine Towne) przygnębia Claire, która zaczyna dopatrywać się podejrzanych rzeczy w zachowaniach sąsiadów. Słyszy głosy, widzi odbicie obcej kobiety w wodzie. Im bardziej zagłębia się w rozwiązanie zagadek nawiedzonego domu i tajemniczego zniknięcia sąsiadki, tym bardziej jej szczęście małżeńskie okazuje się pozorne...', 'https://image.tmdb.org/t/p/w500/uj2WqQSg6EXLUY3seJY7iNBPvvr.jpg', 129, 'United States of America', 'en', 'https://www.youtube.com/watch?v=s6nTJMdrGVU');
