INSERT INTO public.movies (movie_id, title, release_date, description, poster_url, duration_minutes, country, original_language, trailer_url) VALUES (1204, 'Spragnieni miłości', '2000-09-29', 'Hongkong, 1962 r. Uchodźcy z Szanghaju, którzy z nadzieją na lepsze życie licznie przybywają do tej brytyjskiej kolonii, wynajmują każdy, nawet najbardziej obskurny kąt. Wyizolowani, a jednocześnie podlegający nieustannej kontroli sąsiadów, przybysze żyją w zamkniętych społecznościach, tłocząc się w ciasnych pomieszczeniach, zarówno w domach jak i w miejscach pracy. Pewnego dnia do sąsiadujących ze sobą dwóch klitek w jednym z takich przepełnionych domów wprowadzają się równocześnie - sekretarka Su Chan (Maggie Cheung) z mężem i redaktor jednej z gazet Chow Mo-Wan (Tony Leung) z żoną. Żona Chow z powodu obowiązków służbowych często przebywa poza domem. Mąż Su od dłuższego czasu jest podróży służbowej. Kolejne dni w tym ludzkim "mrowisku", których rytm wyznacza jedynie praca, są jałowe i nudne.', 'https://image.tmdb.org/t/p/w500/mjkr1IamzDiL5mLIbnuhiYOXLqg.jpg', 98, 'Hong Kong', 'cn', 'https://www.youtube.com/watch?v=m8GuedsQnWQ');
